import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createInventoryItemsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createInventoryItemsWorkflow(req.scope)
    .run({
      input: {
        items: [{
          sku: "shirt",
          location_levels: [{
            location_id: "sloc_123",
          }]
        }]
      }
    })

  res.send(result)
}

